-- How the household divides the rent: its agreement model.
--
-- 'equal' shares each month's rent equally between the residents taking part;
-- 'room_tiered' charges each of them the base rent of the room they occupy.
-- It is the household's standing choice: each month's rent is generated by it
-- unless that month is generated otherwise. Existing leases keep the equal
-- split they have always had.

ALTER TABLE rent_lease_config
    ADD COLUMN rent_split_mode TEXT NOT NULL DEFAULT 'equal'
        CHECK (rent_split_mode IN ('equal', 'room_tiered'));
